import torch

def gen_inputs(ctx, device):
    shape = tuple(ctx['a__shape'])
    dtype = getattr(torch, ctx['a__dtype'])
    if dtype in (torch.float16, torch.float32, torch.bfloat16, torch.float64):
        a = torch.randn(shape, dtype=dtype, device=device)
    elif dtype in (torch.int8, torch.int16, torch.int32, torch.int64):
        a = torch.randint(-8, 8, shape, dtype=dtype, device=device)
    else:
        a = torch.zeros(shape, dtype=dtype, device=device)
    return {
        'a': a,
        'size': list(a.shape),
        'stride': list(a.stride()),
        'dtype': a.dtype,
        'device': a.device,
        'layout': a.layout,
    }

def run(a, size, stride, dtype, device, layout):
    return torch._assert_tensor_metadata(a, size, stride, dtype, device=device, layout=layout)
